        "desc": "<h2><span class=\"mw-headline\" id=\"Effect\">Эффект</span></h2>\n<p>При включении, оно <b>нейтрализует</b> эффекты <b>Голод</b>, <b>Яд</b>, <b>Слепота</b>, <b>Замешательство</b>, <b>Тьма</b>, <b>Утомление при</b> <b>добыче</b>, <b>Замедление</b>, <b>Слабость</b>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Burden\" title=\"Effects/Burden\"><b>Бремя</b></a>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Fragility\" title=\"Effects/Fragility\"><b>Хрупкость</b></a> и <b>Проклятие</b>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Fatal_Poison\" title=\"Effects/Fatal Poison\"><b>Смертельный яд</b></a>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Paralysis\" title=\"Effects/Paralysis\"><b>Паралич</b></a>, <b>Гипноз</b> и <b><a href=\"https://tensura.wiki.gg/wiki/Effects/Petrification\" title=\"Effects/Petrification\">Окаменение</a></b>.\n</p>\n<p>Нейтрализует <a href=\"https://tensura.wiki.gg/wiki/Damage_Types#Abnormal\" title=\"Damage Types\"><span style=\"color:#AA00FF\">аномальный</span></a> урон\n<br/>\nЗаражение не подпадает под действие этого навыка\n<br/>\n</p>",
        "desc_en": "<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, it <b>nullifies</b> the effects of <b>Hunger</b>, <b>Poison</b>, <b>Blindness</b>, <b>Confusion</b>, <b>Darkness</b>, <b>Mining</b> <b>Fatigue</b>, <b>Slowness</b>, <b>Weakness</b>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Burden\" title=\"Effects/Burden\"><b>Burden</b></a>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Fragility\" title=\"Effects/Fragility\"><b>Fragility</b></a> and <b>Curse</b>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Fatal_Poison\" title=\"Effects/Fatal Poison\"><b>Fatal Poison</b></a>, <a href=\"https://tensura.wiki.gg/wiki/Effects/Paralysis\" title=\"Effects/Paralysis\"><b>Paralysis</b></a>, <b>Hypnosis</b> and <b><a href=\"https://tensura.wiki.gg/wiki/Effects/Petrification\" title=\"Effects/Petrification\">Petrification</a></b>.\n</p>\n<p>Nullifies <a href=\"https://tensura.wiki.gg/wiki/Damage_Types#Abnormal\" title=\"Damage Types\"><span style=\"color:#AA00FF\">Abnormal</span></a> Damage\n<br/>\nInfection is unaffected by this\n<br/>\n</p>"
