        "desc": "<p>Нейтрализация огненных атак — это навык сопротивления в Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Эффект</span></h2>\n<p>При включении, <b>нейтрализует</b> все виды <b>Огонь</b> урона.\n<br/>\n<br/>\n</p>",
        "desc_en": "<p>Flame Attack Nullification is a Resistance Skill in Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, <b>nullifies</b> all forms of <b>Fire</b> damage.\n<br/>\n<br/>\n</p>"
