        "desc": "<p>Нейтрализация атак светом — это навык сопротивления в Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Эффект</span></h2>\n<p>При включении, <b>нейтрализует</b> все виды <b>Свет</b> урона.\n<br/>\n<br/>\n</p>",
        "desc_en": "<p>Light Attack Nullification is a Resistance Skill in Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, <b>nullifies</b> all forms of <b>Light</b> damage.\n<br/>\n<br/>\n</p>"
