        "desc": "<h2><span class=\"mw-headline\" id=\"Effect\">Эффект</span></h2>\n<p>При включении, оно <b>нейтрализует</b> эффекты боли от слабых атак\n</p>\n<h2><span class=\"mw-headline\" id=\"Tips\">Советы</span></h2>\n<ul><li>Просто много раз получайте урон от физических атак — и готово</li></ul>",
        "desc_en": "<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, it <b>nullifies</b> pain effects from weaker attacks\n</p>\n<h2><span class=\"mw-headline\" id=\"Tips\">Tips</span></h2>\n<ul><li>Just get hit a lot with physical attacks and that's it</li></ul>"
