        "desc_en": "<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, it <b>nullifies all forms of Poison damage.</b>\n<br/>\n</p>\n<ul><li class=\"mw-empty-elt\"></li></ul>\n<p><br/>\n</p>"
