        "desc": "<p>Сопротивление пространственным атакам — это навык сопротивления в Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Эффект</span></h2>\n<p>При включении нейтрализует пространственные атаки.\n<br/>\n<br/>\n</p>",
        "desc_en": "<p>Spatial Attack Resistance is a Resistance Skill in Tensura: Reincarnated.\n</p>\n<h2><span class=\"mw-headline\" id=\"Effect\">Effect</span></h2>\n<p>When toggled, it negates spatial attacks.\n<br/>\n<br/>\n</p>"
