        "desc": "<p>Усильте свои атаки эффектом Паралича; после освоения его можно применять автоматически.\n</p>\n<h2><span class=\"mw-headline\" id=\"Usage\">Использование</span></h2>\n<h3><span class=\"mw-headline\" id=\"Passive\">Пассивный</span></h3>\n<ul><li>[Пассивный — в слоте] — Накладывает <a class=\"new\" href=\"https://tensura.wiki.gg/wiki/Effect/Paralysis?action=edit&amp;redlink=1\" rel=\"nofollow\" title=\"Effect/Paralysis (page does not exist)\">Паралич</a> на цель (можно переключить после освоения). 0 MP</li></ul>",
